 static IEnumerable<T> Find<T>(DependencyObject root)where T:DependencyObject{if(root is T value)yield return value;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Find<T>(VisualTreeHelper.GetChild(root,i)))yield return child;}
 [TestMethod]public void CompleteHostActualCaptureButtonAndFreeCanvasLayout()
 {
  Exception? failure=null;bool complete=false;string stage="startup";var thread=new Thread(()=>{try{var app=new App();app.InitializeComponent();var busy=false;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(120)};timer.Tick+=async(_,_)=>{if(busy||app.MainWindow is not MainWindow{IsLoaded:true,DataContext:MainViewModel main} window)return;busy=true;try{
    var output=PlanningCanvasConsistencyTests.Root;var pictures=Path.Combine(output,"hosted");Directory.CreateDirectory(pictures);stage="planning-project";var planning=main.PlanningPage!;var project=Guid.NewGuid();var repository=new RAWSelectionAssistant.Core.Services.Database.SqliteProjectRepository(new RAWSelectionAssistant.Core.Services.Database.PixelTartDatabase(RAWSelectionAssistant.Core.Utilities.AppDataPaths.DatabaseFile));await repository.UpsertAsync(new RAWSelectionAssistant.Core.Models.PhotoProjectRecord{Id=project,Name="画布固定版本 · 合成验收"});main.ForceExitTutorial();main.Settings.Appearance.SidebarCollapsed=true;main.NavigateCommand.Execute("Planning");await planning.LoadAsync(project);planning.DocumentTitle="透明拼贴 · 策划版本";Assert.IsTrue(await planning.FlushAsync());var canvas=await PlanningCanvasConsistencyTests.Mixed(project,Path.Combine(RAWSelectionAssistant.Core.Utilities.AppDataPaths.DataDirectory,"FreeCanvas"));var store=new CanvasDocumentStore(Path.Combine(RAWSelectionAssistant.Core.Utilities.AppDataPaths.DataDirectory,"FreeCanvas"));await store.SaveAsync(canvas);await planning.LoadAsync(project);planning.ContentPage="情绪板";await Task.Delay(100);stage="planning-view";var view=Find<PlanningCenterView>((DependencyObject)window.Content).Single(v=>v.IsVisible);view.Render();stage="capture-button";var button=Find<Button>(view).Single(b=>(b.Content as string)?.StartsWith("插入/更新画布版本")==true);button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var until=DateTime.UtcNow.AddSeconds(15);while(planning.DocumentCanvasRevisions.Count!=1&&DateTime.UtcNow<until)await Task.Delay(20);Assert.AreEqual(1,planning.DocumentCanvasRevisions.Count,planning.SaveStatus);var old=planning.DocumentCanvasRevisions[0].PreviewPngBase64;foreach(int width in new[]{1366,1920}){window.WindowState=WindowState.Normal;window.Width=width;window.Height=width==1366?768:1080;window.UpdateLayout();view.Render();Capture((FrameworkElement)window.Content,$"OFFSCREEN-planning-fixed-{width}.png");}
    var changed=canvas with{Objects=canvas.Objects.Select(o=>o.IsText?o with{Text="第二次手动更新"}:o).ToArray()};await store.SaveAsync(changed);view.Render();Assert.AreEqual(old,planning.DocumentCanvasRevisions.Single().PreviewPngBase64);button=Find<Button>(view).Single(b=>(b.Content as string)?.StartsWith("插入/更新画布版本")==true);button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));until=DateTime.UtcNow.AddSeconds(15);while(planning.DocumentCanvasRevisions.Count!=2&&DateTime.UtcNow<until)await Task.Delay(20);Assert.AreEqual(2,planning.DocumentCanvasRevisions.Count,planning.SaveStatus);Assert.AreEqual(old,planning.DocumentCanvasRevisions[0].PreviewPngBase64);Assert.IsTrue(await planning.FlushAsync());await planning.LoadAsync(project);planning.ContentPage="情绪板";view.Render();Assert.AreEqual(2,planning.DocumentCanvasRevisions.Count);
    stage="asset-library-host";main.NavigateCommand.Execute("AssetLibrary");await Task.Delay(150);var host=Find<AssetLibraryWorkspaceHost>((DependencyObject)window.Content).Single();var descriptor=await new RAWSelectionAssistant.Core.Services.AssetLibrary.AssetLibraryContainerService().CreateAsync(Path.Combine(output,"owned-test.ptlibrary"),"合成画布验收库");await host.SwitchToContainerAsync(descriptor.ContainerPath);var page=await host.InitializeForProductHarnessAsync();Assert.IsNotNull(page);main.NavigateCommand.Execute("AssetLibrary");await page.ShowCanvasAsync(changed);await Task.Delay(100);stage="canvas-view";var canvasView=Find<FreeCanvasView>((DependencyObject)window.Content).First(v=>v.IsVisible);canvasView.Editor.Select(changed.Objects.First(o=>o.IsImage&&!o.Hidden).ObjectId);await canvasView.Surface.LoadPreviewsAsync();foreach(int width in new[]{1366,1920}){window.WindowState=WindowState.Normal;window.Width=width;window.Height=width==1366?768:1080;window.UpdateLayout();await Task.Delay(180);window.UpdateLayout();canvasView.Surface.Fit();Assert.AreEqual(width,((FrameworkElement)window.Content).ActualWidth,1,"Actual client DIP, not requested outer width");Capture((FrameworkElement)window.Content,$"OFFSCREEN-free-canvas-{width}.png");}Assert.IsTrue(await canvasView.FlushAsync());main.NavigateCommand.Execute("Planning");await planning.LoadAsync(project);planning.ContentPage="情绪板";view.Render();foreach(int width in new[]{1366,1920}){window.WindowState=WindowState.Normal;window.Width=width;window.Height=width==1366?768:1080;window.UpdateLayout();view.Render();((ScrollViewer)view.FindName("DocumentScroll")).ScrollToEnd();window.UpdateLayout();Capture((FrameworkElement)window.Content,$"OFFSCREEN-planning-two-versions-{width}.png");}Assert.AreEqual(2,planning.DocumentCanvasRevisions.Count);complete=true;
    void Capture(FrameworkElement target,string name){target.UpdateLayout();var b=new RenderTargetBitmap((int)target.ActualWidth,(int)target.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(target);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using var f=File.Create(Path.Combine(pictures,name));e.Save(f);}
   }catch(Exception e){failure=new InvalidOperationException(stage+": "+e.Message,e);}finally{timer.Stop();app.Shutdown();}};timer.Start();app.Run();}catch(Exception e){failure=e;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();Assert.IsTrue(thread.Join(TimeSpan.FromMinutes(2)));if(failure is not null)throw failure;Assert.IsTrue(complete);
 }
